RSpec.describe Timekeeping::Alerts, "reference_unavailable per company" do
  it "raises the reference_unavailable alert for the failing company even when pooling every company would stay under 1%" do
    body = {
      "window_seconds" => 300,
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 101, "windows" => [
          { "window_start" => "2026-03-03T12:00:00Z", "writes" => 98, "reference_unavailable" => 2,
            "latency_ms_sum" => 4000, "latency_ms_buckets" => { "50" => 100 } }
        ] },
        { "company_id" => 202, "windows" => [
          { "window_start" => "2026-03-03T12:00:00Z", "writes" => 1000, "reference_unavailable" => 0,
            "latency_ms_sum" => 40_000, "latency_ms_buckets" => { "50" => 1000 } }
        ] }
      ],
      "outbox_lag" => []
    }
    metrics_client = Object.new
    metrics_client.define_singleton_method(:fetch) { body }

    gathered = Timekeeping::AlertSignals.gather(metrics_client:, now: Time.utc(2026, 3, 3, 12, 6))
    alerts = described_class.evaluate(gathered.fetch(:signals))

    # "It logs each alert with `company_id`." for "`503 reference_unavailable`
    # over 1% of writes for 5 minutes;": 101 fails 2 of 100 in its completed
    # window, while all companies pooled fail 2 of 1100, under 1%.
    expect(alerts.map(&:company_id)).to eq([101])
  end
end

