RSpec.describe Timekeeping::Alerts, "section 11.3 thresholds" do
  let(:alerts_table_now) { Time.utc(2026, 3, 3, 12, 7) }

  # A completed 12:00-12:05 window for one company, with the given buckets.
  def alerts_table_metrics(company_id: 5, writes: 100, unavailable: 0, buckets: { "50" => writes + unavailable },
                           bounds: [25, 50, 100, 200, 300, 500, 1000, 2500, 5000], overflow: "inf")
    { "window_seconds" => 300, "latency_bucket_bounds_ms" => bounds, "overflow_bucket" => overflow,
      "total_field" => "writes + reference_unavailable", "outbox_lag" => [],
      "companies" => [{ "company_id" => company_id, "windows" => [
        { "window_start" => "2026-03-03T12:00:00Z", "writes" => writes, "reference_unavailable" => unavailable,
          "latency_ms_sum" => 0, "latency_ms_buckets" => buckets }
      ] }] }
  end

  # For every table row: signals at the first value past its threshold, and
  # signals just under it (the limit itself where the limit is reachable).
  def alerts_table_cases
    now = alerts_table_now
    lag = ->(age) { { owner: "timekeeping", outbox_lag_by_owner: { "timekeeping" => [{ "company_id" => 5, "oldest_unsent_age_seconds" => age }] } } }
    intent = ->(age) { { pending_intents: [{ company_id: 5, oldest_created_at: now - age }] } }
    moving = ->(seconds) { { ownership_moving: { started_at: now - seconds, planned_pause_seconds: 120 } } }
    stale = ->(count) { { stale_generation_refusals: [{ company_id: 5, handoff_step: nil, count: }] } }
    counted = ->(key, count) { { key => [{ company_id: 5, count: }] } }
    {
      "outbox_lag" => { at: lag.call(301), under: lag.call(300) },
      "pending_invoice_operation_intent" => { at: intent.call(601), under: intent.call(600) },
      "ownership_moving" => { at: moving.call(121), under: moving.call(120) },
      "stale_generation" => { at: stale.call(1), under: stale.call(0) },
      "reference_unavailable_rate" => { at: { write_metrics: alerts_table_metrics(writes: 98, unavailable: 2) },
                                        under: { write_metrics: alerts_table_metrics(writes: 99, unavailable: 1) } },
      "prepare_refusal" => { at: counted.call(:prepare_refusals, 1), under: counted.call(:prepare_refusals, 0) },
      "reconciliation_difference" => { at: counted.call(:reconciliation_differences, 1),
                                       under: counted.call(:reconciliation_differences, 0) },
      "financial_snapshot_change" => { at: counted.call(:financial_snapshot_changes, 1),
                                       under: counted.call(:financial_snapshot_changes, 0) },
      "entry_write_p95_latency" => { at: { write_metrics: alerts_table_metrics(buckets: { "300" => 94, "500" => 6 }) },
                                     under: { write_metrics: alerts_table_metrics(buckets: { "300" => 95, "500" => 5 }) } }
    }
  end

  def alerts_table_evaluate(signals)
    described_class.evaluate({ now: alerts_table_now }.merge(signals))
  end

  it "has an at-threshold and a just-under case for every row of the table" do
    expect(alerts_table_cases.keys).to eq(described_class::TABLE.map(&:name))
  end

  described_class::TABLE.map(&:name).each do |row_name|
    it "fires #{row_name} at its threshold and stays quiet just under it" do
      cases = alerts_table_cases.fetch(row_name)

      expect(alerts_table_evaluate(cases.fetch(:at)).map(&:name)).to eq([row_name])
      expect(alerts_table_evaluate(cases.fetch(:under))).to eq([])
    end
  end

  it "freezes the table and every row in it" do
    expect(described_class::TABLE).to be_frozen
    expect(described_class::TABLE).to all(be_frozen)
  end

  it "stays quiet one unit below the duration limits" do
    lag = { owner: "timekeeping", outbox_lag_by_owner: { "timekeeping" => [{ "company_id" => 5, "oldest_unsent_age_seconds" => 299 }] } }
    intent = { pending_intents: [{ company_id: 5, oldest_created_at: alerts_table_now - 599 }] }

    expect(alerts_table_evaluate(lag.merge(intent))).to eq([])
  end

  it "divides by writes plus reference_unavailable, so 1 refusal beside 100 writes stays quiet" do
    expect(alerts_table_evaluate(write_metrics: alerts_table_metrics(writes: 100, unavailable: 1))).to eq([])
  end

  it "reads the bucket bounds from the metrics body while keeping the 300 ms limit" do
    custom = ->(buckets) { alerts_table_metrics(bounds: [100, 300, 500], overflow: "beyond", buckets:) }

    expect(alerts_table_evaluate(write_metrics: custom.call({ "100" => 50, "300" => 45, "500" => 5 }))).to eq([])
    fired = alerts_table_evaluate(write_metrics: custom.call({ "100" => 50, "300" => 44, "500" => 6 }))
    expect(fired.map { |alert| [alert.name, alert.value, alert.threshold] }).to eq([["entry_write_p95_latency", 500, 300]])
  end

  it "treats a p95 in the overflow bucket as over every bound" do
    alerts = alerts_table_evaluate(write_metrics: alerts_table_metrics(buckets: { "inf" => 20 }))

    expect(alerts.map { |alert| [alert.name, alert.value] }).to eq([["entry_write_p95_latency", Float::INFINITY]])
  end

  it "never judges a window still in progress" do
    in_progress = alerts_table_metrics(writes: 0, unavailable: 5, buckets: { "inf" => 5 })
    in_progress["companies"][0]["windows"][0]["window_start"] = "2026-03-03T12:05:00Z"

    expect(alerts_table_evaluate(write_metrics: in_progress)).to eq([])
  end

  it "ignores a stale_generation refusal recorded during a handoff" do
    signals = { stale_generation_refusals: [{ company_id: 5, handoff_step: "freeze", count: 3 }] }

    expect(alerts_table_evaluate(signals)).to eq([])
  end

  it "judges only the current owner's outbox" do
    signals = { owner: "monolith", outbox_lag_by_owner: {
      "timekeeping" => [{ "company_id" => 5, "oldest_unsent_age_seconds" => 3600 }],
      "monolith" => [{ "company_id" => 5, "oldest_unsent_age_seconds" => 10 }]
    } }

    expect(alerts_table_evaluate(signals)).to eq([])
  end

  it "names no company on the global ownership_moving alert" do
    alerts = alerts_table_evaluate(ownership_moving: { started_at: alerts_table_now - 121, planned_pause_seconds: 120 })

    expect(alerts.map { |alert| [alert.name, alert.company_id] }).to eq([["ownership_moving", nil]])
  end

  it "raises no alert for a signal that is absent" do
    expect(alerts_table_evaluate(owner: "timekeeping", ownership_moving: nil, write_metrics: nil)).to eq([])
  end
end

RSpec.describe Timekeeping::Alerts, "folded partial-window and custom overflow cases" do
  # "Move alerts_2_spec's partial-window case into alerts_spec.rb" and "Keep every distinct case once."
  it "evaluates a custom overflow key and a newer partial window in the single alerts spec" do
    now = Time.utc(2026, 3, 3, 12, 7)
    window = lambda do |start, writes, unavailable, buckets = { "25" => writes + unavailable }|
      { "window_start" => start, "writes" => writes, "reference_unavailable" => unavailable,
        "latency_ms_sum" => 0, "latency_ms_buckets" => buckets }
    end
    partial = {
      "window_seconds" => 300, "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf", "total_field" => "writes + reference_unavailable", "outbox_lag" => [],
      "companies" => [
        { "company_id" => 7, "windows" => [window.call("2026-03-03T12:00:00Z", 47, 3),
                                           window.call("2026-03-03T12:05:00Z", 1, 0)] },
        { "company_id" => 8, "windows" => [window.call("2026-03-03T12:05:00Z", 0, 1)] },
        { "company_id" => 9, "windows" => [window.call("2026-03-03T12:00:00Z", 100, 1)] }
      ]
    }
    overflow = {
      "window_seconds" => 300, "latency_bucket_bounds_ms" => [100, 300, 500], "overflow_bucket" => "beyond",
      "total_field" => "writes + reference_unavailable", "outbox_lag" => [],
      "companies" => [
        { "company_id" => 11, "windows" => [window.call("2026-03-03T12:00:00Z", 20, 0, { "beyond" => 20 })] },
        { "company_id" => 12, "windows" => [window.call("2026-03-03T12:00:00Z", 20, 0, { "300" => 20 })] }
      ]
    }

    reference = described_class.evaluate(now:, write_metrics: partial).select { |alert| alert.name == "reference_unavailable_rate" }
    latency = described_class.evaluate(now:, write_metrics: overflow).select { |alert| alert.name == "entry_write_p95_latency" }

    expect(reference.map(&:company_id)).to eq([7])
    expect(latency.map { |alert| [alert.company_id, alert.value] }).to eq([[11, Float::INFINITY]])
  end
end
